window.ScripturaLexicons.BDAG_PART_0308 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-01\" data-source=\"BDAG\" data-search=\"προσφεύγω verbo refugiar-se, fugir para BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσφεύγω</td><td>verbo</td><td>refugiar-se, fugir para</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-02\" data-source=\"BDAG\" data-search=\"προσφιλής, ές adjetivo agradável, amável BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσφιλής, ές</td><td>adjetivo</td><td>agradável, amável</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-03\" data-source=\"BDAG\" data-search=\"προσφορά, ᾶς, ἡ substantivo feminino oferta, sacrifício BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσφορά, ᾶς, ἡ</td><td>substantivo feminino</td><td>oferta, sacrifício</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-04\" data-source=\"BDAG\" data-search=\"προσφωνέω verbo dirigir a palavra, chamar, convocar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσφωνέω</td><td>verbo</td><td>dirigir a palavra, chamar, convocar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-05\" data-source=\"BDAG\" data-search=\"προσχαίρω verbo alegrar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσχαίρω</td><td>verbo</td><td>alegrar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-06\" data-source=\"BDAG\" data-search=\"πρόσχυσις, εως, ἡ substantivo feminino aspersão, derramamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόσχυσις, εως, ἡ</td><td>substantivo feminino</td><td>aspersão, derramamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-07\" data-source=\"BDAG\" data-search=\"προσψαύω verbo tocar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσψαύω</td><td>verbo</td><td>tocar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-08\" data-source=\"BDAG\" data-search=\"προσωπολημπτέω verbo mostrar parcialidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσωπολημπτέω</td><td>verbo</td><td>mostrar parcialidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-09\" data-source=\"BDAG\" data-search=\"προσωπολήμπτης, ου, ὁ substantivo masculino aquele que mostra parcialidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσωπολήμπτης, ου, ὁ</td><td>substantivo masculino</td><td>aquele que mostra parcialidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-10\" data-source=\"BDAG\" data-search=\"προσωπολημψία, ας, ἡ substantivo feminino parcialidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσωπολημψία, ας, ἡ</td><td>substantivo feminino</td><td>parcialidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-11\" data-source=\"BDAG\" data-search=\"πρόσωπον, ου, τό substantivo neutro rosto, presença, pessoa, superfície, aparência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόσωπον, ου, τό</td><td>substantivo neutro</td><td>rosto, presença, pessoa, superfície, aparência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-12\" data-source=\"BDAG\" data-search=\"προτάσσω verbo fixar, determinar de antemão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προτάσσω</td><td>verbo</td><td>fixar, determinar de antemão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-13\" data-source=\"BDAG\" data-search=\"προτείνω verbo estender, distender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προτείνω</td><td>verbo</td><td>estender, distender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-14\" data-source=\"BDAG\" data-search=\"πρότερος, α, ον adjetivo anterior, outrora, superior BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρότερος, α, ον</td><td>adjetivo</td><td>anterior, outrora, superior</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-15\" data-source=\"BDAG\" data-search=\"προτίθημι verbo propor, expor publicamente, planejar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προτίθημι</td><td>verbo</td><td>propor, expor publicamente, planejar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-16\" data-source=\"BDAG\" data-search=\"προτρέπω verbo exortar, incentivar, persuadir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προτρέπω</td><td>verbo</td><td>exortar, incentivar, persuadir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-17\" data-source=\"BDAG\" data-search=\"προτρέχω verbo correr à frente, ultrapassar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προτρέχω</td><td>verbo</td><td>correr à frente, ultrapassar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-18\" data-source=\"BDAG\" data-search=\"προϋπάρχω verbo existir anteriormente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προϋπάρχω</td><td>verbo</td><td>existir anteriormente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-19\" data-source=\"BDAG\" data-search=\"προφανερόω verbo revelar de antemão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προφανερόω</td><td>verbo</td><td>revelar de antemão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0308-20\" data-source=\"BDAG\" data-search=\"πρόφασις, εως, ἡ substantivo feminino motivo, justificativa, pretexto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόφασις, εως, ἡ</td><td>substantivo feminino</td><td>motivo, justificativa, pretexto</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0308-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφεύγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσφεύγω</span> 2 aor. <span class=\"greek\">προσέφυγον</span>; 2 perf. <span class=\"greek\">προσπέφευγα</span> (Plut., Pomp. 643 [46, 7], Cic. 3, 5; Herodian 3, 9, 2; PMagd 13, 13 [III a.C.]; BGU 180, 16; POxy 488, 23; Sym.; JosAs 12:7 cód. A [p. 55, 16 Bat.]; Philo, Det. Pot. Ins. 62; Jos., Ant. 1, 311, Vi. 154; Just.) fugir para, fugir em busca de refúgio junto a, com dat. de coisa ou pessoa <span class=\"greek\">τινί</span> (Cornutus 20 p. 38, 8) 1 Cl 20:11; IPhld 5:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφιλής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσφιλής</span>, <span class=\"greek\">ές</span> (Aeschyl., Hdt. e outros; SEG XXIX, 784, 1 e 3 [v. New Docs 4, 171 para outras ref. epigráficas]; pap., LXX, ativo e passivo; Ar. 15, 5 [ativo]) em nossa literatura somente passivo. Relativo ao que causa prazer ou deleite, agradável, aprazível, encantador, amável (assim também Diod S 5, 39, 4; PSI 361, 9 [251/250 a.C.]; BGU 1043, 24; Sir 4:7; 20:13; Jos., Ant. 1, 258; cf. o uso adverbial OGI 331, 9) abs. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:8</a>. <span class=\"greek\">λόγῳ</span> <span class=\"greek\">πρ</span>. agradável ao <span class=\"greek\">λόγος</span> Dg 11:2 conj. (v. o aparato crítico; Diod S 2, 49, 2; 6, 7, 6 <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῖς</span>; Dio Chrys. 16 [33], 28 <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span>; 70 [20], 21 <span class=\"greek\">τῇ</span> <span class=\"greek\">θεῷ</span>; Jos., Ant. 1, 258; 17, 149).—DELG s.v. <span class=\"greek\">φίλος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφορά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσφορά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">προσφέρω</span>; Soph.+; pap., LXX; TestLevi 3:6; 14:5; EpArist 170; Joseph., Just.; Hippol., Ref. 6, 16, 2)</p><p class=\"entry-text\">① o ato de trazer como expressão voluntária (‘apresentar, oferecer’: Pla., Aristot., Polyb.; Did., Gen. 125, 8), em nossa literatura tanto no sentido literal como figurado de sacrificar, oferecer (Sir 46:16 <span class=\"greek\">προσφορὰ</span> <span class=\"greek\">ἀρνός</span>), seguido de gen. objetivo <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">προσφορᾶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> <span class=\"greek\">Ἰησοῦ</span> mediante a oferta do corpo de Jesus em sacrifício <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:10</a>. Cf. vv. 14, 18 (v. Windisch, Hdb., excurs. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:18</a>). <span class=\"greek\">προσφορὰς</span> <span class=\"greek\">ποιεῖν</span> mandar fazer sacrifícios <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:17</a>; 1 Cl 40:4 (Just., D. 29, 8; 67, 8). Com <span class=\"greek\">λειτουργίαι</span> v. 2. <span class=\"greek\">ἀνθρωποποίητος</span> <span class=\"greek\">πρ</span>. uma oferta feita pelo homem B 2:6 (a acepção 2 também é provável). <span class=\"greek\">προσφορᾶς</span> <span class=\"greek\">γενομένης</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Παύλου</span> quando um sacrifício fora feito por Paulo AcPl Ha 6, 37.</p><p class=\"entry-text\">② aquilo que se traz como expressão voluntária (‘presente, dádiva’: Theophr., Char. 30, 19), em nossa literatura em uso figurado e literal, oferta (Sir 14:11; 34:18, 19 e outros; TestLevi 14:5), com <span class=\"greek\">ὁλοκαύτωμα</span> MPol 14:1. Com <span class=\"greek\">θυσία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:5</a> (Ps 39:7). Com <span class=\"greek\">θυσίαι</span>, <span class=\"greek\">ὁλοκαυτώματα</span> <span class=\"greek\">κτλ</span>. (v. Da 3:38; Jos., Ant. 11, 77) v. 8 (Ps 39:7); B 2:4; <span class=\"greek\">ἀνθρωποποίητος</span> <span class=\"greek\">προσφορά</span> um sacrifício feito por um ser humano v. 6 (a acepção 1 também é provável; v. acima). <span class=\"greek\">προσηνέχθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">προσφορά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:26</a> (<span class=\"greek\">προσφέρω</span> 2a). Jesus é chamado <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀρχιερεὺς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προσφορῶν</span> <span class=\"greek\">ἡμῶν</span> o Sumo Sacerdote de nossas ofertas, por levar as orações dos cristãos à presença de Deus 1 Cl 36:1. <span class=\"greek\">ἡ</span> <span class=\"greek\">προσφορὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐθνῶν</span> a oferta que consiste nos gentios (isto é, aqueles dentre ‘as nações’ que se tornaram cristãos) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:16</a>. Para a interpretação de <span class=\"greek\">ἐθνῶν</span> como subjetivo, a oferta que os gentios fazem, v. A-MDenis, RSPT 42, ’58, 405f.—DELG s.v. <span class=\"greek\">φέρω</span> D. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφωνέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσφωνέω</span> imperf. <span class=\"greek\">προσεφώνουν</span>; 1 aor. <span class=\"greek\">προσεφώνησα</span>; inf. aor. pass. <span class=\"greek\">προσεφωνηθῆναι</span> 1 Esdr. 6:6 (Hom. e outros; ins., pap., LXX; EpArist 306; Joseph.).</p><p class=\"entry-text\">① chamar em voz alta ou falar a, chamar, dirigir a palavra (Hom. e outros, em regra com ac. de pessoa), com dat. de pessoa (Diod S 4, 48, 1; Diog. L. 7, 7; PPetr II, 38b, 3 [242 a.C.]; PTebt 27, 109; Mitt-Wilck I/2, 27 verso, 15.—Cf. Eus., HE 4, 3 [introd. a Qua.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:32</a>; 23:20. <span class=\"greek\">τῇ</span> <span class=\"greek\">Ἑβραί̈δι</span> <span class=\"greek\">διαλέκτῳ</span> <span class=\"greek\">προσεφώνει</span> <span class=\"greek\">αὐτοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:2</a>; sem dat. de pessoa, 21:40; 22:2 D. Igualmente abs. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:20</a> v.l.</p><p class=\"entry-text\">② chamar para junto de si, chamar, convocar, com a implicação de interesses comuns <span class=\"greek\">τινά</span> alguém (Jos., Ant. 7, 156) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:13</a> (D <span class=\"greek\">ἐφώνησεν</span>); 13:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:2</a> D.—DELG s.v. <span class=\"greek\">φωνή</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσχαίρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσχαίρω</span> (Plut., Ant. 29, 4; Pr 8:30) alegrar-se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:15</a> D.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσχυσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόσχυσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (Just., A II, 12, 5; Ps.-Clem., Hom. 2, 44. De <span class=\"greek\">προσχέω</span> [Ex 24:6; 29:21 e outros]) ato de pôr líquido sobre algo, derramamento, aspersão, espalhamento <span class=\"greek\">ἡ</span> <span class=\"greek\">πρόσχυσις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἵματος</span> a aspersão do sangue (sobre as ombreiras das portas) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:28</a> (v. Ex 12:22).—DELG s.v. <span class=\"greek\">χέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσψαύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσψαύω</span> (Pind. e outros; TestSol 2:6; Jos., Bell. 7, 348) estender a mão para tocar, tocar <span class=\"greek\">τινί</span> algo (Herophil. [300 a.C.] em Galen II p. 570, 12 K.) <span class=\"greek\">ἑνὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δακτύλων</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">προσψαύετε</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">φορτίοις</span> não tocais os fardos com um de vossos dedos Lk 11:46: a hipérbole acentua a falta de consideração para com aquele que é oprimido.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσωπολημπτέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσωπολημπτέω</span> (eds. também -<span class=\"greek\">ληπτέω</span>; esta palavra e as duas seguintes, estreitamente relacionadas, até agora foram encontradas somente em escritores cristãos. Baseiam-se no <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">λαμβάνειν</span> da LXX, que, por sua vez, é calcado no hebraico [v. <span class=\"greek\">πρόσωπον</span> 1b<span class=\"greek\">α</span>, fim]. Sobre a grafia com ou sem <span class=\"greek\">μ</span>, v. <span class=\"greek\">λαμβάνω</span>, início) mostrar parcialidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:9</a>.—DELG s.v. <span class=\"greek\">πρόσωπον</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσωπολήμπτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσωπολήμπτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (v. <span class=\"greek\">προσωπολημπτέω</span>.—Leontius 4 p. 10, 14 emprega <span class=\"greek\">προσωπολήπτης</span> [que é, em última análise, uma palavra bíblica] fora de um contexto escriturístico, como elemento da fala popular) aquele que mostra parcialidade, de Deus <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">πρ</span>. ele não é alguém que mostra parcialidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:34</a> (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:11</a>).—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσωπολημψία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσωπολημψία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (eds. também -<span class=\"greek\">ληψία</span>; v. <span class=\"greek\">προσωπολημπτέω</span>) parcialidade, mencionada como pecado, com outros pecados Pol 6:1. Não se encontra em Deus (TestJob 43:13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:25</a>. Pl. <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">προσωπολημψίαις</span> conservar a fé enquanto se mostra parcialidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:1</a> (Goodsp, Probs. 142f).—EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσωπον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόσωπον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hom.+; empréstimo na literatura rabínica).</p><p class=\"entry-text\">① a parte anterior da cabeça</p><p class=\"entry-text\">ⓐ lit. rosto, semblante <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:16f</a>; 17:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.65\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:65</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:29</a> (v. <span class=\"greek\">εἶδος</span> 1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:15ab</a> (Chariton 2, 2, 2 <span class=\"greek\">θαυμάζουσαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">θεῖον</span>; Damasc., Vi. Isid. 80 <span class=\"greek\">Πρόκλος</span> <span class=\"greek\">ἐθαύμαζε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">Ἰσιδώρου</span> <span class=\"greek\">πρόσωπον</span>, <span class=\"greek\">ὡς</span> <span class=\"greek\">ἔνθεον</span> <span class=\"greek\">ἦν</span>; Marinus, Vi. Procli 23); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:7</a> duas vezes, 13 (JMorgenstern, Moses with the Shining Face: HUCA 2, 1925, 1–28); cf. v. 18; 4:6; mas nas duas últimas passagens há uma transição do rosto de Moisés para um uso simbólico de <span class=\"greek\">πρ</span>. (v. 1b<span class=\"greek\">β</span><span lang=\"he\" dir=\"rtl\">ג</span> abaixo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:7</a>; 9:7ab; 10:1; IEph 15:3 (cf. 1b<span class=\"greek\">β</span><span lang=\"he\" dir=\"rtl\">ו</span>); MPol 12:1; Hv 3, 10, 1; B 5:14; GJs 17:2; 18:2 (códices). <span class=\"greek\">ἐμβριθεῖ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πρ</span>. MPol 9:2 (v. <span class=\"greek\">ἐμβριθής</span>). <span class=\"greek\">ποίῳ</span> <span class=\"greek\">προσώπῳ</span> GJs 13:1b. <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γενέσεως</span> <span class=\"greek\">αὐτοῦ</span> o rosto com que nasceu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:23</a> (<span class=\"greek\">γένεσις</span> 2a). <span class=\"greek\">ἐμπτύειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">τινος</span> cuspir no rosto de alguém (v. <span class=\"greek\">ἐμπτύω</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.67\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:67</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">δέρειν</span> <span class=\"greek\">τινά</span> golpear alguém no rosto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:20</a>. <span class=\"greek\">τύπτειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρ</span>. GJs 13:1a. <span class=\"greek\">συνέπεσεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">αὐτοῦ</span> seu semblante descaiu ou se desfigurou 1 Cl 4:3; cf. v. 4 (Gen 4:6 e 5; JosAs 13:8). <span class=\"greek\">πίπτειν</span> <span class=\"greek\">ἐπὶ</span> (<span class=\"greek\">τὸ</span>; o artigo geralmente falta; B-D-F §255, 4; 259, 1; cf. Rob. 792) <span class=\"greek\">πρ</span>. <span class=\"greek\">αὐτοῦ</span> cair sobre o próprio rosto em sinal de devoção (=<span lang=\"he\" dir=\"rtl\">נָפַל</span> <span lang=\"he\" dir=\"rtl\">עַל</span> <span lang=\"he\" dir=\"rtl\">פָּנָיו</span>; cf. Gen 17:3; Ruth 2:10; TestAbr A 9 p. 86, 16 [Stone p. 20]; JosAs 14:4 e outros; ApcSed 14:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:6</a>; 26:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:11</a>; 11:16. Sem <span class=\"greek\">αὐτοῦ</span> (Gen 17:17; Num 14:5; Jos., Ant. 10, 11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:12</a>; 17:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:25</a>.</p><p class=\"entry-text\">ⓑ presença pessoal ou circunstância relacional, fig.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. em toda sorte de imagens que, em grande parte, representam o uso do AT, e nas quais o rosto deve frequentemente ser entendido como sede da faculdade de ver. <span class=\"greek\">Βλέπειν</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">πρόσωπον</span> ver face a face <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:12</a> (cf. Gen 32:31 [Jos., Ant. 1, 334 <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πρόσωπον</span>]; Judg 6:22. V. HRiesenfeld, ConNeot 5, ’41, 19; 21f [resumos de quatro artigos]). <span class=\"greek\">κλίνειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:5</a> (<span class=\"greek\">κλίνω</span> 1). <span class=\"greek\">πρ</span>. <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ποιοῦντας</span> <span class=\"greek\">κακά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:12</a>; 1 Cl 22:6 (ambos Ps 33:17). <span class=\"greek\">ἐπίφανον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">σου</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἡμᾶς</span> (<span class=\"greek\">ἐπιφαίνω</span> 1) 60:3 (v. Num 6:25). <span class=\"greek\">ἐμφανισθῆναι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">προσώπῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (<span class=\"greek\">ἐμφανίζω</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:24</a>. <span class=\"greek\">βλέπειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">τινος</span>, isto é, de Deus (<span class=\"greek\">βλέπω</span> 1a, <span class=\"greek\">ὁράω</span> A1c e v. JBoehmer, Gottes Angesicht: BFCT 12, 1908, 321–47; EGulin, D. Antlitz Jahwes im AT: Annal. Acad. Scient. Fenn. 17, 3, 1923; FNötscher, ‘Das Anges. Gottes schauen’ nach bibl. u. babylon. Auffassung 1924) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:10</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:4</a>. <span class=\"greek\">ὁρᾶν</span>, <span class=\"greek\">ἰδεῖν</span> ou <span class=\"greek\">θεωρεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">τινος</span> ver o rosto de alguém, isto é, ver alguém (presente) pessoalmente (UPZ 70, 5 [152/151 a.C.] <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἄν</span> <span class=\"greek\">με</span> <span class=\"greek\">ἶδες</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπον</span>. V. Gen 32:21; 43:3, 5; 46:30 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:25</a>, 38; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:17b</a>; 3:10; IRo 1:1; v. IPol 1:1. <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπόν</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:1</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">προσώπῳ</span> <span class=\"greek\">ἀγνοούμενος</span> desconhecido de rosto, isto é, pessoalmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:22</a> (<span class=\"greek\">ἀγνοέω</span> 1b). <span class=\"greek\">ἀπορφανισθέντες</span> <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">προσώπῳ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">καρδίᾳ</span> (dat. de especificação) tornados órfãos pela separação de vós pessoalmente, não de coração (ou exteriormente, não interiormente) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:17a</a>. <span class=\"greek\">ἐκζητεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρόσωπα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span> (<span class=\"greek\">ἐκζητέω</span> 1) B 19:10; D 4:2. <span class=\"greek\">ἀποστρέφειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> (<span class=\"greek\">ἀποστρέφω</span> 1) 1 Cl 18:9 (Ps 50:11); 16:3 (Is 53:3). <span class=\"greek\">στερεῖν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">τινός</span> B 13:4 (Gen 48:11).—<span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">στηρίζειν</span> (v. <span class=\"greek\">στηρίζω</span> 2 e cf. SAntoniades, Neotestamentica: Neophilologus 14, 1929, 129–35) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:51</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">πορευόμενον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἰερουσαλήμ</span> seu rosto estava voltado para Jerusalém v. 53 (cf. 2 Km 17:11).—<span class=\"greek\">θαυμάζειν</span> <span class=\"greek\">πρόσωπον</span> lisonjear <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 16</a> (PsSol 2:18; v. também <span class=\"greek\">θαυμάζω</span> 1b<span class=\"greek\">α</span>). <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">πρόσωπον</span> (=<span lang=\"he\" dir=\"rtl\">נָשָׂא</span> <span lang=\"he\" dir=\"rtl\">פָנִים</span>; cf. Sir 4:22; 35:13; 1 Esdr 4:39; v. Thackeray p. 43f; B-D-F p. 3, nota 5; Rob. 94) mostrar parcialidade ou favoritismo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:21</a>; B 19:4; D 4:3. <span class=\"greek\">λαμβ</span>. <span class=\"greek\">πρόσωπόν</span> <span class=\"greek\">τινος</span> (cf. Mal 1:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:6</a>. V. PKatz, Kratylos 5, ’60, 161.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. regido por preposições, em usos nos quais <span class=\"greek\">πρ</span>. exige em muitos casos um equivalente dinâmico</p><p class=\"entry-text\"><span lang=\"he\" dir=\"rtl\">א</span> .<span class=\"greek\">ἀπὸ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">τινός</span> da presença de alguém (JosAs 28:10; Just., A I, 36, 1; v. Vi. Aesopi W 104 v.l. p. 188 última linha P. <span class=\"greek\">ἐπιστολὴ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Αἰσώπου</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:20</a>; (para longe) de alguém ou de algo (Ctesias: 688 Fgm. 9 Jac. <span class=\"greek\">φυγεῖν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">Κύρου</span>; LXX; PsSol 4:8 e outros; Herodas 8, 59 <span class=\"greek\">ἔρρ</span>’ <span class=\"greek\">ἐκ</span> <span class=\"greek\">προσώπου</span>=desaparece da minha vista; TestAbr A 2 p. 78, 11 [Stone p. 4] <span class=\"greek\">ἐκ</span> <span class=\"greek\">προσώπου</span>: aqui por causa do composto <span class=\"greek\">ἐξέρχομαι</span>) 5:41; 7:45; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:16</a> (Is 2:10, 19, 21); 12:14; 20:11 (cf. Ex 14:25; Josh 10:11; Sir 21:2; 1 Macc 5:34 e frequentemente) 1 Cl 4:8 (v. <span class=\"greek\">ἀποδιδράσκω</span>), 10 (v. as passagens citadas para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:11</a> acima); 18:11 (Ps 50:13; <span class=\"greek\">ἀπο</span>[<span class=\"greek\">ρ</span>]<span class=\"greek\">ρίπτω</span> 2); 28:3 (Ps 138:7).</p><p class=\"entry-text\"><span lang=\"he\" dir=\"rtl\">ב</span> .<span class=\"greek\">εἰς</span> <span class=\"greek\">πρόσωπον</span>: (Aesop, Fab. 302 P.= <span class=\"greek\">εἰς</span> <span class=\"greek\">Ζηνὸς</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">ἔρχεσθαι</span>=diante da face de Zeus) <span class=\"greek\">εἰς</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐκκλησιῶν</span> diante das congregações (lit. ‘na face de’) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:24</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">φαινόμενά</span> <span class=\"greek\">σου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πρόσωπον</span> aquilo que se apresenta a teus olhos, isto é, o mundo visível IPol 2:2. <span class=\"greek\">βλέπειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πρόσωπόν</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:14</a> (v. <span class=\"greek\">βλέπω</span> 4). Na face de alguém, isto é, em sua presença Hv 3, 6, 3 conj. (cf. POxy 903, 2; BGU 909, 12).</p><p class=\"entry-text\"><span lang=\"he\" dir=\"rtl\">ג</span> . <span class=\"greek\">ἐν</span> <span class=\"greek\">προσώπῳ</span> (Maximus Tyr. 38, 1a) <span class=\"greek\">ἐν</span> <span class=\"greek\">προσώπῳ</span> <span class=\"greek\">Χριστοῦ</span> diante da face de Cristo, que olha com aprovação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:10</a> (cf. Pr 8:30; Sir 35:4), ou como representante de Cristo (REB); diferentemente em 4:6 na face de Cristo (v. 1a acima).</p><p class=\"entry-text\"><span lang=\"he\" dir=\"rtl\">ד</span> . <span class=\"greek\">κατὰ</span> <span class=\"greek\">πρόσωπον</span> face a face, (presente) pessoalmente (Polyb. 24, 15, 2; Diod S 19, 46, 2; Plut., Caesar 716 [17, 8]; IMagnMai 93b, 11; IPriene 41, 6; OGI 441, 66 [81 a.C.]; PLond II, 479, 6 p. 256 [III d.C.?]; POxy 1071, 1) B 15:1. (Oposto a <span class=\"greek\">ἀπών</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:1</a>. <span class=\"greek\">Παῦλος</span>, <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">γενόμενος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">πρόσωπον</span> Pol 3:2. <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κατηγορούμενος</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">ἔχοι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">κατηγόρους</span> antes que o acusado encontre seus acusadores face a face <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:16</a>, <span class=\"greek\">κατὰ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ἀντέστην</span> opus-me a ele face a face <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:11</a> (cf. Diod S 40, 5a, de uma acusação <span class=\"greek\">κατὰ</span> <span class=\"greek\">πρόσωπον</span>; 2 Macc 7:6; Jos., Ant. 5, 46; 13, 278).—<span class=\"greek\">κατὰ</span> <span class=\"greek\">πρόσωπον</span> com parcialidade, com favoritismo B 19:7; D 4:10.—<span class=\"greek\">τὰ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">πρόσωπον</span> o que está diante de vossos olhos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:7</a>.—Usado com gen. como uma prep. (PPetr III, 1 II, 8 <span class=\"greek\">κατὰ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱεροῦ</span>; LXX; Jos., Ant. 3, 144; 9, 8) <span class=\"greek\">κατὰ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">τινος</span> diante ou na presença de alguém (Jos., Ant. 11, 235) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:13</a>; 16:9 D; 1 Cl 35:10 (Ps. 49:21).</p><p class=\"entry-text\"><span lang=\"he\" dir=\"rtl\">ה</span> . <span class=\"greek\">μετὰ</span> <span class=\"greek\">προσώπου</span>: <span class=\"greek\">πληρώσεις</span> <span class=\"greek\">με</span> <span class=\"greek\">εὐφροσύνης</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:28</a> (Ps 15:11); <span class=\"greek\">μετά</span> A 2<span class=\"greek\">γ</span> <span lang=\"he\" dir=\"rtl\">ג</span>.</p><p class=\"entry-text\"><span lang=\"he\" dir=\"rtl\">ו</span> . <span class=\"greek\">πρὸ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">τινός</span> (LXX; TestAbr A 12 p. 91, 4 [Stone p. 30] <span class=\"greek\">πρὸ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τραπέζης</span>; GrBar 1:4; v. Johannessohn, Präp. 184–86) diante de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:27</a> (sobre as três passagens, cf. Mal 3:1).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.76\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:76</a> v.l. (v. Ex 32:34); 9:52 (v. Ex 23:20); 10:1; 1 Cl 34:3 (v. Is 62:11). IEph 15:3 (cf. 1a).—<span class=\"greek\">πρὸ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εἰσόδου</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:24</a> (<span class=\"greek\">εἴσοδος</span> 2).</p><p class=\"entry-text\">② presença corporal integral, pessoa (Polyb. 5, 107, 3; 8, 13, 5; 12, 27, 10; 27, 7, 4; Diod S 37, 12, 1; Plut., Mor. 509b; Epict. 1, 2, 7; Vett. Val. v. índice; Just., A I, 36, 2; POxy 1672, 4 [37–41 d.C.] <span class=\"greek\">ξένοις</span> <span class=\"greek\">προσώποις</span>=a estranhos; 237 VII, 34; PRyl 28, 88. Cf. Phryn. p. 379 Lob., também o comentário de Lob. p. 380; KPraechter, Philol 63, 1904, 155f) <span class=\"greek\">ὀλίγα</span> <span class=\"greek\">πρόσωπα</span> poucas pessoas 1 Cl 1:1; <span class=\"greek\">ἓν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">δύο</span> <span class=\"greek\">πρ</span>. 47:6. <span class=\"greek\">τὰ</span> <span class=\"greek\">προγεγραμμένα</span> <span class=\"greek\">πρ</span>. as pessoas acima mencionadas IMg 6:1. Certamente cabe aqui também <span class=\"greek\">ἐκ</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">προσώπων</span> por muitas (pessoas) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:11</a> (de Lutero à NRSV e outros; ‘rosto’ é preferido por Heinrici, Plummer e outros.—Com esta expressão, cf. Diod S 15, 38, 4 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τρίτου</span> <span class=\"greek\">προσώπου</span>=[reivindicações foram feitas] por uma terceira ‘parte’, isto é, Tebas, contra Esparta e Atenas).</p><p class=\"entry-text\">③ a superfície exterior de algo, face=superfície <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> (Gen 2:6; 7:23; 11:4, 8 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:26</a>; B 11:7 (Ps 1:4); e 6:9 provavelmente pertence também a esta acepção.</p><p class=\"entry-text\">④ aquilo que se apresenta sob determinada forma ou caráter a um observador, coisas exteriores, aparência, oposto a <span class=\"greek\">καρδία</span> (1 Km 16:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:12</a>. <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">εἰρήνης</span> (oposto a <span class=\"greek\">πονηρίαι</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">καρδίαις</span>) Hv 3, 6, 3. <span class=\"greek\">ἡ</span> <span class=\"greek\">εὐπρέπεια</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">αὐτοῦ</span> (isto é, da erva e das flores) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:11</a>. Da aparência do céu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:3</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:56</a> (v. Ps 103:30).—SSchlossmann, Persona u. <span class=\"greek\">Πρόσωπον</span> im röm. Recht u. christl. Dogma 1906; RHirzel, Die Person; Begriff u. Name derselben im Altertum: SBBayAk 1914, Heft 10; HRheinfelder, Das Wort ‘Persona’; Gesch. seiner Bed. 1928; FAltheim, Persona: ARW 27, 1929, 35–52; RAC I 437–40; BHHW I 93f. B. 216.—DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προτάσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προτάσσω</span> (Aeschyl. e outros; Thu. 3, 52; ins., pap.; TestSol 6:11 L; Jos., Ant. 2, 340; Ath., R. 1 p. 49, 15 e outros) dispor algo previamente, fixar, determinar, atribuir (de antemão) (Soph., Trach. 164; Aristot., Probl. 30, 11; 2 Macc 8:36) part. perf. pass. <span class=\"greek\">προτεταγμένοι</span> <span class=\"greek\">καιροί</span> em vez de <span class=\"greek\">προστετ</span>. <span class=\"greek\">κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:26</a> D (v. <span class=\"greek\">προστάσσω</span>, fim).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προτείνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προτείνω</span> 1 aor. <span class=\"greek\">προέτεινα</span> (Trag., Hdt.+; ins., pap.; LXX quase sempre em 2 Macc e sempre acerca de estender as mãos; EpArist 179; Philo; Jos., Vi. 30; Just., A I, 68, 10) estender para diante, estender, distender um criminoso que há de ser açoitado <span class=\"greek\">ὡς</span> <span class=\"greek\">προέτειναν</span> <span class=\"greek\">αὐτον</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἱμᾶσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:25</a>; a tradução depende da compreensão do dat.; v. <span class=\"greek\">ἱμάς</span>.—DELG s.v. <span class=\"greek\">τανυ</span>-. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρότερος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρότερος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (Hom.+; cf. <span class=\"greek\">πρό</span>)</p><p class=\"entry-text\">① relativo a um período de tempo que precede outro período de tempo, anterior</p><p class=\"entry-text\">ⓐ adj. (Hom. e outros) precedente, anterior <span class=\"greek\">ἡ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ἀναστροφή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:22</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">πρ</span>. (subent. <span class=\"greek\">λίθοι</span>) Hs 9, 4, 3. <span class=\"greek\">τάς</span> <span class=\"greek\">χρόας</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">προτέρας</span> 9, 4, 5; <span class=\"greek\">τὰ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ἁμαρτήματα</span> 2 Cl 13:1; Hm 12, 6, 2; Hs 9, 23, 5. <span class=\"greek\">ἡ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ἁμαρτία</span> m 4, 1, 11; pl. v 2, 3, 1; m 4, 3, 3; Hs 6, 1, 4; 8, 11, 3; <span class=\"greek\">αἱ</span> <span class=\"greek\">ἁμαρτίαι</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">πρ</span>. m 4, 3, 1. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ἀγνοήματα</span> Hs 5, 7, 3f. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">παραπτώματα</span> m 4, 4, 4. <span class=\"greek\">ἡ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ὅρασις</span> v 4, 1, 1. <span class=\"greek\">αἱ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">λύπαι</span> 3, 13, 2. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ὁράματα</span> 4, 2, 2. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">χαλεπά</span> 1, 4, 2 v.l. <span class=\"greek\">πρῶτα</span>. <span class=\"greek\">οἱ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">χρόνοι</span> Hs 9, 20, 4. <span class=\"greek\">ἡ</span> <span class=\"greek\">ζωὴ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρ</span>. 9, 16, 2.</p><p class=\"entry-text\">ⓑ o neutro <span class=\"greek\">πρότερον</span> como adv. anteriormente, outrora, em tempos passados (Pind., Hdt.+).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. sem artigo; oposto a <span class=\"greek\">νῦν</span> (Ael. Aristid. 33, 16 K.=51 p. 576 D.; Procop. Soph., Ep. 88) <span class=\"greek\">νῦν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">πρότερον</span> agora e não em tempos passados Dg 1. <span class=\"greek\">πρότερον</span> … <span class=\"greek\">ἔπειτα</span> (Ps.-Clem., Hom. 7, 6; cf. Artem. 2, 39 p. 144, 27f <span class=\"greek\">πρότερον</span> … <span class=\"greek\">εἶτα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:27</a>. Frequentemente o tempo posterior ao designado por <span class=\"greek\">πρ</span>. não é expresso, mas é subentendido pelo contexto: anteriormente, de antemão, previamente (frequentemente Pind., Hdt. e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.50\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:50</a> v.l., 51 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:13</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:6</a>.—Schwyzer I 533f.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. com artigo e funcionando como adj. anterior (Hdt. 6, 87; Aristoph., Equ. 1355; Diod S 17, 69, 3) <span class=\"greek\">αἱ</span> <span class=\"greek\">πρότερον</span> <span class=\"greek\">ἡμέραι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:32</a>. <span class=\"greek\">αἱ</span> <span class=\"greek\">πρότερον</span> <span class=\"greek\">ἐπιθυμίαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:14</a>.—Com artigo, simplesmente em função adverbial <span class=\"greek\">τὸ</span> <span class=\"greek\">πρότερον</span> antes, outrora, anteriormente (X., Mem. 3, 8, 1; Menand., Dyscolus 15; Hero Alex. I, 190, 19; TestAbr A 18 p. 100, 9 e 11 [Stone p. 48]; ApcMos 9; Jos., Ant. 20, 173) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.62\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:62</a>; 7:50; 9:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:13</a>; Hv 3, 3, 5. A primeira vez Hv 3, 12, 1; Hs 9, 1, 3. Assim provavelmente também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:13</a>. Naturalmente a tradução outrora também é provável, mas, de um ponto de vista linguístico, não é possível estabelecer a tese de que Paulo desejava distinguir entre uma visita posterior e uma anterior.</p><p class=\"entry-text\">② anterior a alguém/algo em importância, superior, preferível, mais proeminente (Pla., Lach. 183b <span class=\"greek\">πρότεροι</span> <span class=\"greek\">ἡμῶν</span>; Aristot. Cat. 14b, 5ff <span class=\"greek\">εἰώθασι</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">πολλοὶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐντιμοτέρους</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἀγαπωμένους</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">προτέρους</span> <span class=\"greek\">φάσκειν</span> <span class=\"greek\">εἶναι</span>=as pessoas comuns costumam dizer que aqueles que são especialmente estimados e queridos por elas gozam de prioridade em seu pensamento; Wsd 7:29) <span class=\"greek\">ἄλλοι</span> <span class=\"greek\">σου</span> <span class=\"greek\">πρότεροί</span> <span class=\"greek\">εἰσιν</span> outros são superiores a ti Hv 3, 4, 3.—Como equivalente de um numeral ordinal <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰωάννου</span> <span class=\"greek\">προτέρας</span> <span class=\"greek\">ἐπιστολῆς</span> a primeira carta de João Papias (2:17),—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προτίθημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προτίθημι</span> 1 aor. <span class=\"greek\">προέθηκα</span> LXX; 2 aor. subj. <span class=\"greek\">προθῶ</span>; part. perf. <span class=\"greek\">προτεθεικώς</span> (Just., D. 65, 3). Médio: 2 aor. <span class=\"greek\">προεθέμην</span>. Pass.: 1 aor. part. gen. pl. <span class=\"greek\">προτεθέντων</span> (Ath., R. 15 p. 65, 20); part. perf. <span class=\"greek\">προτεθειμένος</span> LXX (Hom.+; ins., pap., LXX; TestReub 1:6 v.l.; Philo, Joseph.; Ar. 13, 5; Just.; Ath.).</p><p class=\"entry-text\">① pôr algo diante de alguém como algo a ser feito, propor a alguém como tarefa/dever, ativo com dat. <span class=\"greek\">τινί</span> (Soph., Ant. 216; Hdt. 3, 38; 9, 27) <span class=\"greek\">ἐὰν</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">σεαυτῷ</span> <span class=\"greek\">προθῇς</span> <span class=\"greek\">ὅτι</span> Hm 12, 3, 5.</p><p class=\"entry-text\">② apresentar publicamente, expor publicamente, tornar publicamente disponível, médio (Appian, Bell. Civ. 3, 26 §101; Just., D. 65, 3 <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόβλημα</span>), de Cristo <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">προέθετο</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἱλαστήριον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:25</a> (v. <span class=\"greek\">ἱλαστήριον</span>). Mas a voz ativa, pelo menos, parece ter tido também a acepção oferecer (v. SIG 708, 15 com a nota 5 do editor; 714, 16–18, e M-M.; também ZPE 3, ’68, 166 n. 9).</p><p class=\"entry-text\">③ ter algo em mente de antemão, planejar, propor, tencionar, <span class=\"greek\">τὶ</span> algo, médio (Pla., Phdr. 259d; Polyb. 6, 12, 8; Jos., Vi. 290) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:9</a>. Com inf. seguinte (Pla., Rep. 1, 352d, Leg. 1, 638c; Polyb. 8, 13, 3; 11, 7, 3; Jos., C. Ap. 2, 287, Ant. 18, 286; 19, 37) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:13</a> (B-D-F §392, 1a). <span class=\"greek\">ὁ</span> <span class=\"greek\">καιρὸς</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">προέθετο</span> <span class=\"greek\">φανερῶσαι</span> … o tempo que Deus havia determinado para revelar (como parte de um plano e desígnio abrangentes) Dg 9:2.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προτρέπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προτρέπω</span> em nossa literatura somente médio (assim Hom.+; o prefixo põe em relevo o movimento para diante) 1 aor. <span class=\"greek\">προετρεψάμην</span>; 2 aor. pass. 3 sing. <span class=\"greek\">προετράπη</span> (ApcrEzk) promover determinado curso de ação, instar, incentivar, impelir, persuadir (Soph. e outros) <span class=\"greek\">τινά</span> alguém com inf. seguinte (Hyperid. 6, 24; UPZ 110, 165 [164 a.C.]; PRyl 77, 48; BGU 164, 17; 450, 15; 2 Macc 11:7; Jos., Ant. 12, 166; Just., D. 106, 1) 1 Cl 34:4. Abs. (Jos., Ant. 5, 171; 7, 262) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:27</a>.—M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προτρέχω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προτρέχω</span> 2 aor. <span class=\"greek\">προέδραμον</span> (Antiphon e outros; LXX) correr à frente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:4</a> (=ultrapassar correndo; cf. X., An. 1, 5, 2 <span class=\"greek\">προδραμόντες</span> … <span class=\"greek\">πολὺ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἵππων</span> <span class=\"greek\">ἔτρεχον</span> <span class=\"greek\">θᾶττον</span>, de asnos que ‘ultrapassaram correndo’ alguém montado a cavalo, ‘pois corriam muito mais depressa que os cavalos’); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:25</a> D. <span class=\"greek\">πρ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔμπροσθεν</span> correr adiante <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:4</a> (v. <span class=\"greek\">ἔμπροσθεν</span> 1a e cf. Tob 11:3; Job 41:14 v.l.; progredir AcPlCor 2:2).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προϋπάρχω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προϋπάρχω</span> imperf. <span class=\"greek\">προϋπῆρχον</span> intr. existir anteriormente (assim Thu. e outros; Diod S 16, 82, 6; ins., pap.; Job 42:18; Philo, Op. M. 130; Jos., Ant. 1, 290; Just.) com part. seguinte (B-D-F §414, 1; Rob. 1121) <span class=\"greek\">προϋπῆρχεν</span> <span class=\"greek\">μαγεύων</span> ele vinha praticando magia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:9</a> (Jos., Ant. 4, 125 <span class=\"greek\">ἅ</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">προϋπῆρξεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔμπροσθεν</span> <span class=\"greek\">χρόνοις</span> <span class=\"greek\">γενόμενα</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀνθρώποις</span>). <span class=\"greek\">προϋπῆρχον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἔχθρᾳ</span> <span class=\"greek\">ὄντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:12</a> (cf. Diod S 19, 7, 2 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">προϋπαρχούσας</span> <span class=\"greek\">ἔχθρας</span>; Vett. Val. 283, 24 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">προϋπάρχουσαν</span> <span class=\"greek\">ἔχθραν</span>).—DELG s.v. <span class=\"greek\">ἄρχω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προφανερόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προφανερόω</span> 1 aor. <span class=\"greek\">προεφανέρωσα</span>, pass. <span class=\"greek\">προεφανερώθην</span> revelar de antemão/antecipadamente <span class=\"greek\">τὸ</span> <span class=\"greek\">πάθος</span> pass. B 6:7. <span class=\"greek\">τινὶ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> revelar algo a alguém de antemão 3:6. Sem o dat., que se deve suprir pelo contexto 11:1. <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> algo a alguém 7:1. Abs. (com <span class=\"greek\">προετοιμάζειν</span> e seguido de <span class=\"greek\">πληροῦν</span>, o ‘cumprimento’ da revelação) MPol 14:2.—DELG s.v. <span class=\"greek\">φαίνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0308-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόφασις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόφασις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">προφαίνω</span>; Hom+)</p><p class=\"entry-text\">① algo dito em defesa de uma ação, motivo ou razão efetiva, justificativa válida (Pind., Thu. e outros; SIG 888, 137; PLips 64, 8 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πρόφασιν</span> <span class=\"greek\">ταύτην</span>=‘por esta razão’; TestAbr B 3 p. 107, 8 [Stone p. 62], finalidade; TestJob 11:11 <span class=\"greek\">προφάσει</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πενήτων</span>=por amor dos pobres, em favor dos pobres; TestJos 8:5; Philo; Jos., Ant. 13, 427, Vi. 167) <span class=\"greek\">πρ</span>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> ter uma justificativa válida para algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:22</a>.</p><p class=\"entry-text\">② motivo falsamente alegado, pretexto, razão ostensiva, desculpa (Hom. e outros; OGI 669, 15 <span class=\"greek\">προφάσει</span>=sob o pretexto; pap., LXX, Philo; Jos., Bell. 2, 348, Vi. 79; 282; Just., D. 141, 1; Tat.) <span class=\"greek\">προφάσει</span> com motivos falsos (oposto a <span class=\"greek\">ἀληθείᾳ</span>, Thu. 6, 33, 2; cf. Arrian, Anab. 1, 25, 3.—Na realidade têm outros interesses.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:18</a>. Por pretexto, pelas aparências (como se sentissem uma necessidade interior) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:14</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:47</a> (JDerrett, NovT 14, ’72, 1–9: uma ostentação de piedade para conquistar a confiança neles). <span class=\"greek\">προφάσει</span> <span class=\"greek\">ὡς</span> sob o pretexto de que, fingindo que (Philip em Demosth. 18, 77 <span class=\"greek\">πρόφασιν</span> <span class=\"greek\">ὡς</span> com part.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:30</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">πλεονεξίας</span> com um pretexto para (satisfazer) a avareza <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:5</a>.—KDeichgräber, <span class=\"greek\">Πρόφασις</span>: Quellen u. Stud. z. Gesch. der Naturwissenschaften u. d. Med. III/4, ’33; LPearson, Prophasis and Aitia: TAPA 83, ’52, 205–23.—DELG s.v. <span class=\"greek\">φαίνω</span>. M-M. TW. Sv.</p></section></article>"};
